import json
from collections import Counter

# Load trajectories
trajs = []
for f in ['data/trajectories/train_part0.jsonl', 'data/trajectories/train_part1.jsonl']:
    with open(f'/root/autodl-tmp/rl-active-probe-fl/{f}') as fh:
        trajs.extend(json.loads(l) for l in fh)

failed = [t for t in trajs if not t['reward']]
print(f"Total trajs: {len(trajs)}, failed: {len(failed)}")

# For each of the first 5 failed trajectories, extract key info
for i, t in enumerate(failed[:5]):
    print(f'\n=== Failed traj {i}, task_id={t["task_id"]}, task_type={t["task_type"]} ===')
    gf = t["game_file"].split("/train/")[-1] if "/train/" in t["game_file"] else t["game_file"]
    print(f'game_file: {gf[:100]}')

    convs = t['conversations']

    # Find all task descriptions
    task_msgs = []
    for j, m in enumerate(convs):
        if m['role'] == 'user' and 'Your task is to:' in m['content']:
            for line in m['content'].split('\n'):
                if 'Your task is to:' in line:
                    task_msgs.append((j, line.strip()))

    for idx, task in task_msgs:
        print(f'  Task desc at msg[{idx}]: {task}')

    # Extract assistant actions (non-OK)
    actions = []
    for m in convs:
        if m['role'] == 'assistant' and m['content'].strip() != 'OK':
            for line in m['content'].split('\n'):
                if line.strip().startswith('Action:'):
                    actions.append(line.strip())
                    break

    print(f'First 7 actions (of {len(actions)} total):')
    for j, a in enumerate(actions[:7]):
        print(f'  Step {j+1}: {a}')

# Now check: are the first 5 actions identical across all failed trajectories?
print("\n\n=== Cross-trajectory comparison: first 5 actions ===")
action_seqs = []
for t in failed:
    convs = t['conversations']
    actions = []
    for m in convs:
        if m['role'] == 'assistant' and m['content'].strip() != 'OK':
            for line in m['content'].split('\n'):
                if line.strip().startswith('Action:'):
                    actions.append(line.strip())
                    break
    action_seqs.append(tuple(actions[:5]))

seq_counts = Counter(action_seqs)
print(f"Unique first-5-action sequences: {len(seq_counts)}")
for seq, count in seq_counts.most_common(5):
    print(f"\n  Count: {count}")
    for j, a in enumerate(seq):
        print(f"    Step {j+1}: {a}")

# Check what happens at step 6 for failure_step=5 trajectories
print("\n\n=== Step 6 observations for failure_step=5 trajectories ===")
with open('/root/autodl-tmp/rl-active-probe-fl/data/classified/classified_errors.jsonl') as f:
    classified = [json.loads(l) for l in f]

step5_records = [r for r in classified if r.get('failure_step') == 5]
# Check the observation after step 5 (the user message following the 5th assistant message)
for i, r in enumerate(step5_records[:3]):
    convs = r['conversations']
    assistant_count = 0
    for j, m in enumerate(convs):
        if m['role'] == 'assistant' and m['content'].strip() != 'OK':
            assistant_count += 1
            if assistant_count == 5:
                # Next user message is the step 5 observation
                if j+1 < len(convs) and convs[j+1]['role'] == 'user':
                    obs = convs[j+1]['content'][:200]
                    print(f"\nRecord {i} (task_id={r['task_id']}, type={r['task_type']}):")
                    print(f"  Step 5 action: {m['content'].split(chr(10))[-1].strip()[:100]}")
                    print(f"  Step 5 obs: {obs}")
                break
